#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Grids;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Modifiers;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Grids;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Models;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.timeBomb)]
    public class TimeBomb : AIEntityBehaviour, IExplodeContraptionBehaviour
    {
        public TimeBomb(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(EngineEntityProps.FLIP_X, false, priority: VanillaModifierPriorities.FORCE));
            AddModifier(new ColorModifier(EngineEntityProps.COLOR_OFFSET, PROP_COLOR_OFFSET));
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            SetExplosionTimer(entity, TimerHelper.NewSecondTimer(EXPLOSION_SECONDS));
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            if (!entity.IsDead)
            {
                var explosionTimer = GetExplosionTimer(entity);
                Color color = Color.clear;
                if (explosionTimer != null)
                {

                    explosionTimer.Run();
                    if (explosionTimer.PassedInterval(30))
                    {
                        entity.PlaySound(VanillaSoundID.timeBombTick);
                    }
                    if (explosionTimer.PassedFrame(40))
                    {
                        entity.PlaySound(VanillaSoundID.parabotTick);
                    }
                    if (explosionTimer.PassedFrame(20))
                    {
                        entity.PlaySound(VanillaSoundID.parabotTick);
                    }
                    if (explosionTimer.Expired)
                    {
                        entity.TryBehaviourExplodeAndRemove(entity.GetRange(), entity.GetDamage());
                    }
                    if (explosionTimer.Frame <= 30 && explosionTimer.Frame % 4 < 2)
                    {
                        color = Color.white;
                    }
                    else
                    {
                        var x = Mathf.Pow((explosionTimer.MaxFrame - explosionTimer.Frame) / (explosionTimer.MaxFrame / 5f), 3);
                        var alpha = (-Mathf.Cos(x) + 1) * 0.25f;
                        color = new Color(1, 0, 0, alpha);
                    }
                }
                entity.SetProperty(PROP_COLOR_OFFSET, color);
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            var explosionTimer = GetExplosionTimer(entity);
            var frames = explosionTimer?.Frame ?? 0;
            var seconds = Mathf.Clamp(Mathf.FloorToInt(Ticks.ToSeconds(frames)), 0, 99);

            var number0 = seconds % 10;
            var number1 = (seconds / 10) % 10;
            entity.SetModelProperty("Number0", number0);
            entity.SetModelProperty("Number1", number1);
        }
        void IExplodeContraptionBehaviour.Explode(Entity entity, float range, float damage)
        {
            Explode(entity, range, damage);
        }
        public static void Explode(Entity entity, float range, float damage)
        {
            var position = entity.GetCenter();
            var faction = entity.GetFaction();
            var source = new EntitySourceReference(entity);
            ExplodeSingle(entity.Level, position, range, damage, faction, source);

            var tile = entity.GetGrid();
            if (tile != null)
            {
                var buff = tile.NewBuff<TimeBombExplosionBuff>();
                TimeBombExplosionBuff.SetOffset(buff, position - tile.GetEntityPosition());
                TimeBombExplosionBuff.SetDamage(buff, damage);
                TimeBombExplosionBuff.SetRange(buff, range);
                TimeBombExplosionBuff.SetFaction(buff, faction);
                TimeBombExplosionBuff.SetSource(buff, source);
                TimeBombExplosionBuff.SetSpread(buff, (int)(TileDirection.Left | TileDirection.Right));
                tile.AddBuff(buff);
            }

            entity.PlaySound(VanillaSoundID.timeBombExplosion);
            entity.Level.ShakeScreen(10, 0, 15);

            entity.Level.Triggers.RunCallbackFiltered(VanillaLevelCallbacks.POST_CONTRAPTION_DETONATE, new EntityCallbackParams(entity), entity.GetDefinitionID());
        }
        public static void ExplodeSingle(LevelEngine level, Vector3 position, float range, float damage, int faction, ILevelSourceReference? source)
        {
            var effects = new DamageEffectList(VanillaDamageEffects.EXPLOSION, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN, VanillaDamageEffects.MUTE);
            level.Explode(position, range, faction, damage, effects, source);

            var explosionParam = new SpawnParams();
            explosionParam.SetProperty(EngineEntityProps.SIZE, Vector3.one * (range * 2));
            level.SpawnSourced(VanillaEffectID.explosion, position, source, explosionParam);
        }
        public static void SetExplosionTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_EXPLOSION_TIMER, timer);
        public static FrameTimer? GetExplosionTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_EXPLOSION_TIMER);
        public const float EXPLOSION_SECONDS = 10;
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_EXPLOSION_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("explosion_timer");
        public static readonly VanillaEntityPropertyMeta<Color> PROP_COLOR_OFFSET = new VanillaEntityPropertyMeta<Color>("ColorOffset");
    }
}
